        depth = 2,
        instruction = "3x Worgbut of Clan Death, 3x Rallbrog of Clan Death, 3x Vangknok of Clan Death (other Orcs, susceptible to Sleep/Lullaby).",
        action = "note",
        entities = { "Worgbut of Clan Death", "Rallbrog of Clan Death", "Vangknok of Clan Death", "Orc", "Sleep", "Lullaby" },
        zones = {  },
