        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 25,
        marker = "**",
        depth = 2,
        instruction = "Alternatively, have your BRD Lullaby-tank like in Steamed Sprouts: start the fight by casting Foe Lullaby on the RNG. It won't stick, but will cause all the other Orcs to swarm the Bard. Horde Lullaby, wait for them to awake, and repeat.",
        action = "fight",
        entities = { "Lullaby", "Steamed Sprouts", "Foe Lullaby", "RNG", "Orc", "Bard", "Horde Lullaby" },
        zones = {  },
        map_numbers = {  },
