        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 26,
        marker = "*",
        depth = 1,
        instruction = "Next it is imperative you silence the Warmachine. Strangely enough, that hulking thing is actually a White Mage and will cast Curaga quite often waking the horde up and causing problems. (The danger here is not the HP restored from the Curagas, even its Curaga II only restores roughly 190 HP tops. The danger is waking up the horde.) Note that it has caster mob behavior, meaning that... Required details: Curaga II.",
        action = "note",
        entities = { "Curaga II" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 27,
        marker = "*",
        depth = 1,
        instruction = "As such, kill the Warmachine first, Ranger second then pick off the remaining orcs. It does not matter on which orc you do next after the RNG is dead. They are easy prey.",
