        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 28,
        marker = "*",
        depth = 1,
        instruction = "Keep a weak one alive and slept and rest to full. Killing the final orc will trigger an event.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 29,
        marker = "*",
        depth = 1,
        instruction = "Alternative to killing them quicker: have a SMN kill some of the orcs. They are INCREDIBLY weak to Predator Claws.",
        action = "fight",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 30,
        marker = "*",
        depth = 1,
        instruction = "It is possible to get within casting range of the orcs before they aggro, so you can get an initial cast off on Yukvok of Clan Death. (He is the Orc standing the farthest forward. The rest are in a semi-circle just behind him spread out along the far wall of the arena.) However, they are so spread out that Sleepga is ineffective until they all aggro/link and gather together.",
